};

export const Button = React.forwardRef<HTMLButtonElement & HTMLAnchorElement, ButtonProps>(
  (
    {
      variant = "default",
      size = "default",
      depth,
      radius,
      faceColor,
      faceHighlight,
      contentColor,
      baseColor,
      baseShadow,
      href,
      target,
      rel,
      children,
      className = "",
      style,
      disabled,
      ...props
    },
    ref
