    const v = VARIANTS[variant] || VARIANTS.default;
    const s = SIZES[size] || SIZES.default;

    const actualDepth = depth || s.depth;
    const actualRadius = radius || s.radius;

    const customStyles: Record<string, string> = {
      "--tactile-depth": actualDepth,
      "--tactile-radius": actualRadius,
      "--tactile-face": faceColor || v.face,
      "--tactile-face-highlight": faceHighlight || v.highlight,
      "--tactile-content": contentColor || v.content,
      "--tactile-base": baseColor || v.base,
      "--tactile-base-shadow": baseShadow || v.shadow,
    };

    const combinedStyle = {
      ...customStyles,
      ...style,
    } as React.CSSProperties;

    const baseClasses = `group/tactile relative inline-grid w-max shrink-0 cursor-pointer select-none border-0 bg-transparent p-0 pb-[var(--tactile-depth)] font-inherit leading-none focus-visible:rounded-[var(--tactile-radius)] focus-visible:outline-2 focus-visible:outline-slate-700 focus-visible:outline-offset-2 disabled:pointer-events-none disabled:opacity-45 aria-disabled:pointer-events-none aria-disabled:opacity-45 ${className}`;

    const innerContent = (
      <>
        {/* 3D Base extrusion shadow */}
        <span className="absolute inset-x-0 top-[var(--tactile-depth)] bottom-0 rounded-[var(--tactile-radius)] bg-[var(--tactile-base)] shadow-[inset_0_-1px_0_var(--tactile-base-shadow)]" />

        {/* 3D Surface Face with mechanical push kinematics */}
        <span
          className={`relative flex items-center justify-center rounded-[var(--tactile-radius)] bg-[var(--tactile-face)] font-medium text-[var(--tactile-content)] shadow-[inset_0_1px_0_var(--tactile-face-highlight)] transition-transform duration-150 [transition-timing-function:cubic-bezier(0.23,1,0.32,1)] group-active/tactile:translate-y-[var(--tactile-depth)] motion-reduce:transform-none motion-reduce:transition-none [@media(hover:hover)_and_(pointer:fine)]:group-hover/tactile:translate-y-0.5 ${s.inner}`}
        >
          {children}
        </span>
      </>
    );

    if (href) {
      return (
        <a
          ref={ref as React.Ref<HTMLAnchorElement>}
          href={href}
          target={target}
          rel={target === "_blank" ? rel || "noopener noreferrer" : rel}
          style={combinedStyle}
          className={baseClasses}
          aria-disabled={disabled}
        >
          {innerContent}
        </a>
      );
    }

    return (
      <button
        ref={ref as React.Ref<HTMLButtonElement>}
        type="button"
        style={combinedStyle}
        className={baseClasses}
        disabled={disabled}
        {...props}
      >
        {innerContent}
      </button>
    );
  }
);

