          outline: 1.5px solid var(--ink, #0f172a);
          outline-offset: 2px;
        }
      `}</style>

      <nav
        ref={trackRef as React.RefObject<HTMLElement>}
        className={`gnav ${className}`}
        data-orientation={vertical ? "vertical" : "horizontal"}
        style={vars}
        aria-label={ariaLabel}
      >
        <span className="gnav-ind" data-phase={phase} style={style} aria-hidden />

        {items.map((item) => {
          const isSelected = active === item.key;
          const isIconOnly = Boolean(item.icon && !item.showLabel);
          const isSwatch = Boolean(item.color || variant === "swatches");

          let slotStyle: React.CSSProperties = {};
          if (isSwatch || isIconOnly) {
            const dim = size === "xs" ? 24 : size === "default" ? 36 : 28;
            slotStyle = {
              width: `${dim}px`,
              height: `${dim}px`,
              padding: 0,
            };
          } else {
            const h = size === "xs" ? 24 : size === "default" ? 36 : 28;
            const padH = size === "xs" ? 8 : size === "default" ? 14 : 10;
            slotStyle = {
              minWidth: `${h}px`,
              height: `${h}px`,
              padding: `0 ${padH}px`,
            };
          }

          return (
            <button
              key={item.key}
              ref={(el) => {
                refs.current[item.key] = el;
              }}
              type="button"
              className="gnav-item"
              data-active={isSelected}
              aria-label={item.label || item.key}
              title={item.label || item.key}
              aria-current={isSelected ? "page" : undefined}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                select(item.key);
                onChange?.(item.key);
              }}
              style={slotStyle}
            >
              {item.color ? (
                <span
                  className={`block rounded-full border transition-transform duration-150 ${
                    isSelected ? "scale-110" : "opacity-80 hover:opacity-100"
                  }`}
                  style={{
                    backgroundColor: item.color,
                    borderColor: item.darkOutline || item.color,
                    width: size === "xs" ? "12px" : size === "default" ? "16px" : "14px",
                    height: size === "xs" ? "12px" : size === "default" ? "16px" : "14px",
                  }}
                />
              ) : isIconOnly ? (
                <span className="flex items-center justify-center text-current">{item.icon}</span>
              ) : (
                <span
                  className={`flex items-center justify-center gap-1.5 font-mono ${
                    size === "xs" ? "text-[11px]" : size === "default" ? "text-xs" : "text-xs"
                  }`}
                >
                  {item.icon}
                  {item.label && <span>{item.label}</span>}
                </span>
              )}
            </button>
          );
        })}
      </nav>
    </>
  );
}

/* ── Default GlassIconBar ────────────────────────────────── */
const NAV_CORNER = 26;

export function GlassIconBar(props: {
  glyph?: number;
  axis?: "row" | "column";
  dilate?: number;
  bounce?: number;
  speed?: number;
  hug?: number;
  corner?: number;
}) {
  const g = props.glyph ?? 17;
  const icons: SelectBarItem[] = [
    { key: "home", label: "Home", icon: <HouseIcon size={g} strokeWidth={2} /> },
    { key: "search", label: "Search", icon: <MagnifyingGlassIcon size={g} strokeWidth={2} /> },
    { key: "files", label: "Files", icon: <FolderIcon size={g} strokeWidth={2} /> },
    { key: "saved", label: "Saved", icon: <BookmarkIcon size={g} strokeWidth={2} /> },
    { key: "you", label: "You", icon: <UserIcon size={g} strokeWidth={2} /> },
  ];

  return (
    <div
      className="relative flex items-center justify-center p-4"
      style={
        {
          "--gnav-r": `${clamp(props.corner ?? NAV_CORNER, 0, NAV_CORNER)}px`,
        } as React.CSSProperties
      }
    >
      <SelectBar items={icons} {...props} />
    </div>
  );
}
